/**
 * NOAA WHATSAPP — Evolution API Webhook Handler
 *
 * Handler ENXUTO: só I/O do WhatsApp via Evolution API (CloudStation).
 * Toda a lógica vive em `_shared/noaa-core/runNoaaTurn.ts` — paridade 100%
 * com noaa-chat (Telegram).
 */

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { runNoaaTurn } from '../_shared/noaa-core/runNoaaTurn.ts'
import { sanitizeNoaMessages, sanitizeNoaOutput } from '../_shared/noaa-core/tools/sanitize_output.ts'
import { getSession, updateSession, insertMessage } from '../_shared/noaa-core/session.ts'
import { sanitizarInput } from '../_shared/noaa-core/tools/guardrails.ts'
import { sendAlert } from '../_shared/noaa-core/tools/alerts.ts'
import { checkRateLimit } from '../_shared/noaa-core/tools/rate_limiter.ts'
import { transcribeAudio } from '../_shared/noaa-core/tools/transcribe_audio.ts'
import { debounceCoalesce } from '../_shared/noaa-core/tools/debounce.ts'

// ════════════════ ENV ════════════════
const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
const EVOLUTION_URL = Deno.env.get('EVOLUTION_API_URL') || ''
const EVOLUTION_KEY = Deno.env.get('EVOLUTION_API_KEY') || ''
const EVOLUTION_INSTANCE = Deno.env.get('EVOLUTION_INSTANCE') || 'cs-cst-evolution-api-b40bf447'

const HANDOFF_TO_ASHLEY_MESSAGES = [
  'Minha equipe já vai te mandar o link de pagamento 💛 Dois minutinhos!',
]

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Content-Type': 'application/json',
}

// ════════════════ EVOLUTION I/O ════════════════

async function evolutionFetch(path: string, init: RequestInit = {}, attempt = 1): Promise<any> {
  const method = (init.method || 'GET').toUpperCase()
  const isWrite = method === 'POST' || method === 'PUT' || method === 'DELETE' || method === 'PATCH'
  const isSendOp = isWrite && (path.includes('/message/send') || path.includes('/sendText') || path.includes('/sendAudio') || path.includes('/sendMedia'))

  const r = await fetch(`${EVOLUTION_URL}${path}`, {
    ...init,
    headers: {
      'apikey': EVOLUTION_KEY,
      'Content-Type': 'application/json',
      ...(init.headers || {}),
    },
  })
  const text = await r.text()

  // Retry 503 SOMENTE em endpoints idempotentes (GET ou writes não-de-envio).
  // Send msg NUNCA retry — Evolution pode ter aceitado o request mesmo retornando 503,
  // e retry duplicaria a msg pro cliente.
  if (r.status === 503 && attempt < 4 && !isSendOp) {
    await new Promise(res => setTimeout(res, attempt * 3000))
    return evolutionFetch(path, init, attempt + 1)
  }

  let parsed: any
  try { parsed = JSON.parse(text) } catch { parsed = text }
  if (!r.ok) {
    const preview = typeof parsed === 'string' ? parsed.slice(0, 200) : JSON.stringify(parsed).slice(0, 200)
    throw new Error(`Evolution ${r.status}: ${preview}`)
  }
  return parsed
}

async function sendWhatsAppMessage(phone: string, text: string): Promise<boolean> {
  try {
    await evolutionFetch(`/message/sendText/${EVOLUTION_INSTANCE}`, {
      method: 'POST',
      body: JSON.stringify({ number: phone.replace(/\D/g, ''), text }),
    })
    return true
  } catch (e) {
    console.error('[NOAA-WA] sendText error:', e)
    return false
  }
}

async function sendPresenceUpdate(phone: string, presence: 'composing' | 'recording' | 'paused') {
  try {
    await evolutionFetch(`/chat/sendPresence/${EVOLUTION_INSTANCE}`, {
      method: 'POST',
      body: JSON.stringify({
        number: phone.replace(/\D/g, ''),
        presence: presence === 'composing' ? 'composing' : presence === 'recording' ? 'recording' : 'paused',
      }),
    })
  } catch { /* best-effort */ }
}

async function sendHumanizedMessages(phone: string, messages: string[]) {
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i]
    await sendPresenceUpdate(phone, 'composing')
    const typingDelay = Math.min(3000, Math.max(800, msg.length * 50))
    await sleep(typingDelay)
    await sendWhatsAppMessage(phone, msg)
    if (i < messages.length - 1) await sleep(300 + Math.random() * 500)
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

// ════════════════ PARSE INCOMING ════════════════

interface ParsedWAMessage {
  phone: string
  senderName: string
  text?: string
  messageType: 'text' | 'audio' | 'image' | 'document'
  rawMessage: any
}

function parseIncoming(body: any): ParsedWAMessage | null {
  // Evolution API: data = { key, message, pushName, messageTimestamp } em messages.upsert
  const data = body.data
  if (!data || !data.key || !data.message) return null
  const msgs = data

  if (msgs.key?.fromMe) return null // msg enviada por nós — não processar

  const phone = String(msgs.key?.remoteJid || '').replace('@s.whatsapp.net', '').replace(/\D/g, '')
  if (!phone || phone.length < 8) return null
  // Ignora grupos
  const jid = String(msgs.key?.remoteJid || '')
  if (jid.includes('@g.us') || jid.includes('@newsletter') || jid.includes('@broadcast')) return null

  const senderName = msgs.pushName || phone

  const message = msgs.message || {}
  let messageType: 'text' | 'audio' | 'image' | 'document' = 'text'
  if (message.audioMessage) messageType = 'audio'
  else if (message.imageMessage) messageType = 'image'
  else if (message.documentMessage) messageType = 'document'

  const text = msgs.messageBody
    || message.conversation
    || message.extendedTextMessage?.text
    || message.imageMessage?.caption
    || ''
  return { phone, senderName, text, messageType, rawMessage: msgs }
}

async function handleIncomingMedia(
  parsed: ParsedWAMessage,
  sessionId: number,
): Promise<{ mediaUrl: string | null; mediaMime: string | null }> {
  if (parsed.messageType === 'text') return { mediaUrl: null, mediaMime: null }

  // Evolution API entrega áudios/imagens/etc CRIPTOGRAFADOS (Baileys). Pra obter
  // o blob decryptado, usa endpoint POST /chat/getBase64FromMediaMessage/{instance}
  // que retorna { base64, mimetype }. Sem isso, fetch direto na url falha (URL é
  // encrypted resource WhatsApp). Bug pré-fix: handleIncomingMedia retornava null
  // → áudios não eram baixados → não eram transcritos.
  const msg = parsed.rawMessage?.message || {}
  const mediaObj = msg.audioMessage || msg.imageMessage || msg.videoMessage || msg.documentMessage
  if (!mediaObj) return { mediaUrl: null, mediaMime: null }

  const instance = parsed.rawMessage?.instance || EVOLUTION_INSTANCE
  const messageKey = parsed.rawMessage?.key
  if (!messageKey) {
    console.error('[NOAA-WA] handleIncomingMedia: sem rawMessage.key')
    return { mediaUrl: null, mediaMime: null }
  }

  let blob: Blob
  let detectedMime = mediaObj.mimetype || mediaObj.mimeType || null

  try {
    // 1. Tenta endpoint Evolution decrypted (preferido)
    const decryptResp = await evolutionFetch(`/chat/getBase64FromMediaMessage/${instance}`, {
      method: 'POST',
      body: JSON.stringify({
        message: { key: messageKey, message: msg },
        convertToMp4: false,
      }),
    }).catch(e => {
      console.warn('[NOAA-WA] getBase64FromMediaMessage falhou:', String(e).slice(0, 200))
      return null
    })

    if (decryptResp && (decryptResp.base64 || decryptResp.data?.base64)) {
      const base64 = decryptResp.base64 || decryptResp.data.base64
      detectedMime = decryptResp.mimetype || decryptResp.data?.mimetype || detectedMime
      // Decode base64 → blob
      const binStr = atob(base64)
      const bytes = new Uint8Array(binStr.length)
      for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i)
      blob = new Blob([bytes], { type: detectedMime || 'application/octet-stream' })
      console.log(`[NOAA-WA] media decryptado via Evolution: ${blob.size} bytes ${detectedMime}`)
    } else {
      // 2. Fallback: tenta fetch direto (raramente funciona, mas tenta)
      const publicUrl = mediaObj?.url || mediaObj?.mediaUrl || null
      if (!publicUrl) {
        console.error('[NOAA-WA] sem url e sem decrypt — abortando media download')
        return { mediaUrl: null, mediaMime: null }
      }
      const res = await fetch(publicUrl)
      blob = await res.blob()
      detectedMime = blob.type || detectedMime
      console.log(`[NOAA-WA] media via fetch direto fallback: ${blob.size} bytes ${detectedMime}`)
    }

    if (!blob || blob.size === 0) {
      console.error('[NOAA-WA] media blob vazio')
      return { mediaUrl: null, mediaMime: null }
    }

    const ext = parsed.messageType === 'audio' ? 'ogg'
      : parsed.messageType === 'image' ? 'jpg'
      : parsed.messageType === 'video' ? 'mp4'
      : 'bin'
    const path = `${sessionId}/${crypto.randomUUID()}.${ext}`
    const { error } = await supabase.storage.from('noaa-media').upload(path, blob, {
      contentType: detectedMime || blob.type || 'application/octet-stream',
    })
    if (error) {
      console.error('[NOAA-WA] Storage upload error:', error)
      return { mediaUrl: null, mediaMime: null }
    }
    return { mediaUrl: path, mediaMime: detectedMime || blob.type || null }
  } catch (e) {
    console.error('[NOAA-WA] Media download/upload error:', e)
    return { mediaUrl: null, mediaMime: null }
  }
}

function phoneToSessionId(phone: string): number {
  const cleaned = phone.replace(/\D/g, '')
  const last10 = cleaned.slice(-10)
  return parseInt(last10, 10)
}

/**
 * Processa eventos de histórico/sync do Baileys (via Evolution webhook):
 *  - messages.upsert: chega array de msgs (pode ser "notify" ou "append")
 *  - messaging-history.set: chega com chats[], messages[], contacts[]
 *  - messages.sent: msg que o OPERADOR enviou (fromMe=true)
 *
 * Arquiva tudo em noaa_messages. NÃO dispara Mia — é histórico passivo.
 */
async function processHistoryEvent(body: any): Promise<{ saved: number; skipped: number }> {
  const ev = body.event as string
  const payload = body.data || {}

  // Normaliza: Evolution manda UMA msg por payload (key+message em data direto)
  let rawMessages: any[] = []
  if (Array.isArray(payload.messages)) {
    rawMessages = payload.messages
  } else if (payload.messages?.messages) {
    rawMessages = payload.messages.messages
  } else if (payload.key && payload.message) {
    // Evolution API: payload é a msg diretamente
    rawMessages = [payload]
  } else if (payload.key) {
    rawMessages = [payload]
  }

  if (rawMessages.length === 0) return { saved: 0, skipped: 0 }

  let saved = 0, skipped = 0
  for (const m of rawMessages) {
    try {
      const key = m.key || m
      const remoteJid: string = key.remoteJid || key.jid || ''
      if (!remoteJid || remoteJid.includes('@g.us') || remoteJid.includes('@newsletter') || remoteJid.includes('@broadcast')) {
        skipped++; continue
      }
      const fromMe = Boolean(key.fromMe)
      const phone = remoteJid.replace(/[^\d]/g, '')
      if (!phone || phone.length < 8) { skipped++; continue }
      const chatIdInterno = parseInt(phone.slice(-10), 10)
      if (!Number.isFinite(chatIdInterno)) { skipped++; continue }

      // Extrai conteúdo texto (vários formatos Baileys)
      const msg = m.message || {}
      const content: string = (
        msg.conversation
        || msg.extendedTextMessage?.text
        || msg.imageMessage?.caption
        || msg.videoMessage?.caption
        || msg.documentMessage?.caption
        || ''
      )
      if (!content && !msg.audioMessage && !msg.imageMessage && !msg.videoMessage && !msg.documentMessage) {
        skipped++; continue
      }

      const ts = m.messageTimestamp ?? m.t ?? key.timestamp
      const createdAt = ts
        ? new Date((Number(ts) > 1e12 ? Number(ts) : Number(ts) * 1000)).toISOString()
        : new Date().toISOString()

      // Garante session existe (observer)
      const { data: existingSession } = await supabase
        .from('noaa_sessions')
        .select('chat_id, customer_phone')
        .eq('chat_id', chatIdInterno)
        .maybeSingle()

      if (!existingSession) {
        await supabase.from('noaa_sessions').insert({
          chat_id: chatIdInterno,
          customer_phone: phone,
          customer_name: m.pushName || phone,
          channel: 'whatsapp',
          mode: 'observer',
          is_active: true,
          conversation_history: [],
          started_at: createdAt,
          last_activity: createdAt,
        })
      } else {
        await supabase.from('noaa_sessions')
          .update({ last_activity: createdAt })
          .eq('chat_id', chatIdInterno)
      }

      // Dedup: não salva se já existe msg com mesmo id/timestamp
      const messageId = key.id || m.id
      if (messageId) {
        const { data: existingMsg } = await supabase
          .from('noaa_messages')
          .select('id')
          .eq('session_id', chatIdInterno)
          .eq('metadata->>wa_message_id', messageId)
          .maybeSingle()
        if (existingMsg) { skipped++; continue }
      }

      // ═══ HUMANO vs NOA ECHO (2026-04-30) ═══
      // fromMe=true vem em DOIS casos:
      //  (a) Noa enviou via Evolution → webhook ecoa de volta. insertMessage da
      //      Noa já gravou com sender_type='noaa' antes do webhook chegar.
      //  (b) Atendente humano digitou no celular conectado ao mesmo número.
      //      ESTA é a msg crítica — precisa marcar sender_type='human' pra
      //      atomic lock trigger setar mode=human + state analyzer detectar.
      // Diferenciação: dedup por content match contra msgs assistant recentes.
      let senderType: 'noaa' | 'human' | null = null
      if (fromMe && content) {
        const ninetySecAgo = new Date(Date.now() - 90_000).toISOString()
        const { data: recentNoa } = await supabase
          .from('noaa_messages')
          .select('id, content, sender_type, created_at')
          .eq('session_id', chatIdInterno)
          .eq('role', 'assistant')
          .gte('created_at', ninetySecAgo)
          .order('created_at', { ascending: false })
          .limit(10)
        const echoMatch = (recentNoa || []).find((r: any) => r.content === content)
        if (echoMatch) {
          // Eco da Noa — atualiza wa_message_id da msg existente e pula insert
          if (messageId) {
            await supabase.from('noaa_messages')
              .update({ metadata: { wa_message_id: messageId, wa_from_me: true, echo_matched: true } })
              .eq('id', echoMatch.id)
          }
          skipped++; continue
        }
        // Sem match → atendente humano digitando. Marca pra atomic lock + analyzer.
        senderType = 'human'
        console.log(`[NOAA-WA] history fromMe=true SEM match Noa → sender_type=human chat=${chatIdInterno} content="${content.slice(0, 80)}"`)
      }

      await supabase.from('noaa_messages').insert({
        session_id: chatIdInterno,
        role: fromMe ? 'assistant' : 'user',
        sender_type: senderType,
        content: content || `[${msg.audioMessage ? 'audio' : msg.imageMessage ? 'imagem' : msg.videoMessage ? 'video' : 'documento'}]`,
        channel: 'whatsapp',
        message_type: msg.audioMessage ? 'audio' : msg.imageMessage ? 'image' : msg.videoMessage ? 'video' : msg.documentMessage ? 'document' : 'text',
        created_at: createdAt,
        metadata: {
          wa_message_id: messageId,
          wa_event: ev,
          wa_from_me: fromMe,
          wa_pushname: m.pushName,
          history_sync: true,
          ...(senderType === 'human' ? { typed_on_phone: true } : {}),
        },
      })
      saved++
    } catch (e) {
      console.error('[NOAA-WA] history msg falhou:', e)
      skipped++
    }
  }

  console.log(`[NOAA-WA] history event ${ev}: saved=${saved} skipped=${skipped}`)
  return { saved, skipped }
}

// ════════════════ MAIN HANDLER ════════════════

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS_HEADERS })

  const url = new URL(req.url)

  if (req.method === 'GET' && url.searchParams.get('setup') === 'true') {
    if (!EVOLUTION_URL || !EVOLUTION_KEY) {
      return new Response(JSON.stringify({ error: 'Evolution API não configurada' }), { status: 500, headers: CORS_HEADERS })
    }
    try {
      const data = await evolutionFetch(`/instance/connectionState/${EVOLUTION_INSTANCE}`, { method: 'GET' })
      return new Response(JSON.stringify({
        webhook: `${SUPABASE_URL}/functions/v1/noaa-whatsapp`,
        evolution_status: data,
      }), { headers: CORS_HEADERS })
    } catch (e) {
      return new Response(JSON.stringify({ error: 'Evolution connection failed', detail: String(e) }), {
        status: 500, headers: CORS_HEADERS,
      })
    }
  }

  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405 })

  // Header interno: self-call de áudio pula re-insert da msg user
  const skipUserInsert = req.headers.get('X-Noaa-Skip-User-Insert') === '1'

  try {
    const body = await req.json()

    // Evolution API envia event name em lowercase.dot OR UPPERCASE_UNDERSCORE.
    // Normaliza pra lowercase.dot pra matchar o handler.
    let ev = String(body.event || '')
    if (ev === ev.toUpperCase() && ev.includes('_')) {
      ev = ev.toLowerCase().replace(/_/g, '.')
    }

    console.log(`[NOAA-WA] webhook recebido: event=${ev} instance=${body.instance}`)

    // ═══ EVENTOS HISTÓRICO / ESTRUTURA (chats, contatos) — arquiva sem disparar Noa ═══
    if (ev === 'messaging-history.set' || ev === 'chats.upsert' || ev === 'message.sent' || ev === 'messages.sent') {
      const result = await processHistoryEvent(body)
      return new Response(JSON.stringify({ ok: true, history: result }), { headers: CORS_HEADERS })
    }

    // ═══ messages.upsert (Evolution): separar realtime vs histórico ═══
    // Baileys emite este evento pra TUDO: msg nova em tempo real OU msg antiga no sync.
    // Regra: msg <60s, não-fromMe → dispara runNoaaTurn (salva via insertMessage abaixo)
    //        caso contrário (histórico OU fromMe) → só arquiva em processHistoryEvent
    if (ev === 'messages.upsert') {
      const payload = body.data || {}
      const msgSingle = (payload.key && payload.message) ? payload : null
      const msgTs = Number(msgSingle?.messageTimestamp || 0)
      const nowSec = Math.floor(Date.now() / 1000)
      const isRecent = msgTs && (nowSec - msgTs < 120)
      const isFromMe = Boolean(msgSingle?.key?.fromMe)

      // Se NÃO é realtime OU é fromMe → só arquiva e retorna (SEM dispatch)
      if (!isRecent || isFromMe || !msgSingle) {
        const archiveResult = await processHistoryEvent(body)
        return new Response(JSON.stringify({ ok: true, history: archiveResult, dispatched: false }), { headers: CORS_HEADERS })
      }
      // Realtime + inbound → NÃO arquiva aqui; fluxo normal abaixo chama insertMessage
    }

    const parsed = parseIncoming(body)
    if (!parsed) return new Response('OK')
    if (!parsed.text && parsed.messageType === 'text') return new Response('OK')

    const sessionId = phoneToSessionId(parsed.phone)
    const textRaw = (parsed.text || '').trim()

    console.log(`[NOAA-WA] ${parsed.senderName} (${parsed.phone}): ${textRaw.slice(0, 100) || `[${parsed.messageType}]`} | instance=${body.instance || EVOLUTION_INSTANCE}`)

    // ── ANTI-INJECTION ──
    const sanitization = sanitizarInput(textRaw)
    const text = sanitization.sanitized
    const isInjectionAttempt = sanitization.flags.includes('injection_attempt')
    if (isInjectionAttempt) {
      console.warn(`[NOAA-WA] Prompt injection chat=${sessionId}: ${textRaw.slice(0, 120)}`)
    }

    await sendPresenceUpdate(parsed.phone, 'composing')

    // ── RATE LIMIT ──
    const rl = await checkRateLimit(sessionId, 20, 60)
    if (!rl.allowed) {
      console.warn(`[NOAA-WA] rate limited chat=${sessionId} count=${rl.count}`)
      await sendWhatsAppMessage(
        parsed.phone,
        'Calma aí, você mandou muitas mensagens rápido 😊 Me dá 1 minutinho e a gente continua.',
      )
      return new Response('OK')
    }

    const session = await getSession(sessionId, 'whatsapp')
    if (parsed.senderName && !session.customer_name) session.customer_name = parsed.senderName
    if (!session.customer_phone) session.customer_phone = parsed.phone

    // ── MEDIA ──
    // skipUserInsert=true: self-call de áudio já inseriu msg do user (com transcrição).
    // Pula handleIncomingMedia (não tem media nesse self-call) e re-insert do user.
    const { mediaUrl, mediaMime } = skipUserInsert
      ? { mediaUrl: null, mediaMime: null }
      : await handleIncomingMedia(parsed, sessionId)
    const messageText = text || (parsed.messageType === 'audio' ? '[audio]' : `[${parsed.messageType}]`)

    const userMessageId = skipUserInsert ? null : await insertMessage({
      sessionId,
      role: 'user',
      content: text || null,
      messageType: parsed.messageType,
      mediaUrl,
      mediaMime,
      channel: 'whatsapp',
      red_flags: isInjectionAttempt ? ['prompt_injection'] : null,
      metadata: {
        wa_phone: parsed.phone,
        wa_sender_name: parsed.senderName,
        wa_message_id: parsed.rawMessage?.key?.id,
        ...(sanitization.flags.length > 0 ? { sanitization_flags: sanitization.flags } : {}),
      },
    })

    if (isInjectionAttempt) {
      await sendAlert({
        kind: 'prompt_injection_attempt',
        severity: 'warning',
        title: 'Tentativa de prompt injection detectada',
        description: `chat_id=${sessionId} msg="${text.slice(0, 200)}"`,
        session_id: sessionId,
        context: { flags: sanitization.flags },
      }).catch(() => {/* best-effort */})
    }

    // ── AUDIO SEM TEXTO — TRANSCRIÇÃO VIA GROQ WHISPER ──
    // CRITICAL FIX 2026-04-28: SÓ responde se a sessão estiver em mode='ai'.
    // 2026-04-29: integrado Groq Whisper. Áudio vira texto, segue flow normal.
    // 2026-04-29 v2: refatorado pra usar self-call (timer fresh) — evita
    // timeout cumulativo: download blob (~2s) + transcribe (~2s) + pipeline
    // (~10-25s) > 10s edge function default. Self-call separa em 2 invocações.
    const isGloballyDisabled = Deno.env.get('NOAA_GLOBAL_DISABLE') === 'true'
    if (parsed.messageType === 'audio' && !text) {
      // SEMPRE transcreve áudio (mesmo em observer/human) pra que catchup futuro
      // possa ler o conteúdo real, não só "[audio]". Skip apenas o RESPONSE quando
      // mode != ai (atendente humano vai ver transcrição no painel e decidir).
      if (mediaUrl) {
        console.log(`[NOAA-WA] audio recebido (mode=${session.mode}) — transcrevendo via Groq Whisper`)
        const tx = await transcribeAudio(mediaUrl, mediaMime)
        if (tx.text && !tx.error) {
          // ✓ Transcrição OK — atualiza msg do user + self-call pipeline
          console.log(`[NOAA-WA] transcrição (${tx.duration_s}s, ${tx.latency_ms}ms): "${tx.text.slice(0, 100)}" — self-call pipeline`)
          if (userMessageId) {
            await supabase.from('noaa_messages').update({
              content: `🎤 ${tx.text}`,
              metadata: {
                wa_phone: parsed.phone,
                wa_sender_name: parsed.senderName,
                wa_message_id: parsed.rawMessage?.key?.id,
                transcription: { text: tx.text, model: tx.model_used, duration_s: tx.duration_s, latency_ms: tx.latency_ms, cost_usd: tx.cost_usd },
              },
            }).eq('id', userMessageId)
          }
          // Loga evento
          try {
            await supabase.from('noaa_session_events').insert({
              session_id: sessionId,
              event_type: 'audio_transcribed',
              description: `Áudio ${tx.duration_s}s transcrito em ${tx.latency_ms}ms`,
              payload: { transcription_preview: tx.text.slice(0, 200), duration_s: tx.duration_s, latency_ms: tx.latency_ms, channel: 'whatsapp' },
            })
          } catch { /* best-effort */ }

          // Self-call SOMENTE se Noa estiver ativa. Em observer/human, transcrição
          // já foi salva no DB; quando supervisor ligar a IA depois, catchup pega
          // a msg com `🎤 transcrição` e processa normalmente.
          if (session.mode === 'ai' && !isGloballyDisabled) {
            const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY') || Deno.env.get('SUPABASE_PUBLISHABLE_KEY')
            const selfUrl = `${SUPABASE_URL}/functions/v1/noaa-whatsapp`
            const selfPayload = {
              instance: body.instance || EVOLUTION_INSTANCE,
              data: {
                key: { remoteJid: parsed.rawMessage?.key?.remoteJid, id: `${parsed.rawMessage?.key?.id}_t` },
                message: { conversation: tx.text },
                pushName: parsed.senderName,
                messageType: 'conversation',
              },
            }
            fetch(selfUrl, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${supabaseAnonKey}`,
                'X-Noaa-Skip-User-Insert': '1',
              },
              body: JSON.stringify(selfPayload),
            }).catch(e => console.error('[NOAA-WA] self-call audio falhou:', e))
          } else {
            console.log(`[NOAA-WA] audio transcrito mas mode=${session.mode} — sem response (catchup futuro vai ler)`)
            // Adiciona msg do user ao history JSONB pra Noa ver no catchup
            session.conversation_history.push({ role: 'user', content: `🎤 ${tx.text}` })
            await updateSession(session)
          }

          return new Response('OK')
        } else {
          // ✗ Transcrição falhou — alerta + canned APENAS se Noa ativa
          console.warn(`[NOAA-WA] transcrição falhou: ${tx.error}`)
          await sendAlert({
            kind: 'audio_transcription_failed',
            severity: 'warning',
            title: 'Transcrição de áudio falhou',
            description: `chat=${sessionId} error=${tx.error}`,
            session_id: sessionId,
          }).catch(() => { /* best-effort */ })
          if (session.mode === 'ai' && !isGloballyDisabled) {
            await sendWhatsAppMessage(
              parsed.phone,
              'Oi! Tive um probleminha pra ouvir seu áudio agora. Pode me mandar por texto? 💚',
            )
            await insertMessage({
              sessionId, role: 'assistant',
              content: 'Oi! Tive um probleminha pra ouvir seu áudio agora. Pode me mandar por texto? 💚',
              channel: 'whatsapp',
            })
            session.conversation_history.push({ role: 'user', content: messageText })
            session.conversation_history.push({
              role: 'assistant',
              content: 'Oi! Tive um probleminha pra ouvir seu áudio agora. Pode me mandar por texto? 💚',
            })
          } else {
            session.conversation_history.push({ role: 'user', content: '🎤 [áudio - falha transcrição]' })
          }
          await updateSession(session)
          return new Response('OK')
        }
      } else {
        // Sem mediaUrl: nem dá pra transcrever. Arquiva sem responder.
        console.log(`[NOAA-WA] audio sem mediaUrl — arquivando sem transcrever`)
        session.conversation_history.push({ role: 'user', content: messageText })
        await updateSession(session)
        return new Response('OK')
      }
    }

    // ═══ DEBOUNCE / COALESCING (5s window) ═══
    const debounce = await debounceCoalesce(supabase, sessionId, { skipDebounce: skipUserInsert })
    if (!debounce.isLeader) {
      return new Response(JSON.stringify({ ok: true, debounced: true, version: debounce.finalVersion }), { headers: CORS_HEADERS })
    }

    // ═══ BATCH COALESCE: pega TODAS msgs do user desde última msg do bot ═══
    // Líder agrupa todas msgs que chegaram durante o debounce window numa só
    // chamada — Noa vê "Brownie\nDressed chocomelo\nAniversario" como um turn.
    let batchText = text
    if (!skipUserInsert) {
      const { data: lastBot } = await supabase
        .from('noaa_messages')
        .select('created_at')
        .eq('session_id', sessionId)
        .in('role', ['assistant', 'supervisor'])
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle()
      const cutoff = lastBot?.created_at || new Date(0).toISOString()
      const { data: userMsgs } = await supabase
        .from('noaa_messages')
        .select('content')
        .eq('session_id', sessionId)
        .eq('role', 'user')
        .gt('created_at', cutoff)
        .order('created_at', { ascending: true })
        .limit(20)
      const concatenated = (userMsgs || []).map((m: any) => String(m.content || '').trim()).filter(Boolean).join('\n')
      if (concatenated && concatenated.length > text.length) {
        console.log(`[NOAA-WA] BATCH: ${userMsgs?.length} msgs coalescidas — "${concatenated.slice(0, 120)}"`)
        batchText = concatenated
      }
    }

    // ── CORE TURN (paridade total com Telegram) ──
    const result = await runNoaaTurn({
      channel: 'whatsapp',
      chatId: sessionId,
      text: batchText,
      senderName: parsed.senderName,
      senderPhone: parsed.phone,
      userMessageId,
      injectionAttempt: isInjectionAttempt,
      // parsed.messageType vem do parseIncomingMessage: 'text'|'audio'|'image'|'document'
      // Tudo != 'text' = mídia anexada.
      userMessageHasMedia: parsed.messageType !== 'text',
    })

    if (result.error) {
      await sendWhatsAppMessage(parsed.phone, 'Desculpa, tive um probleminha aqui. Pode repetir?')
      return new Response('OK')
    }

    // [NO_RESPONSE] Noa avaliou contexto e decidiu ficar quieta — não envia nada.
    if (result.noResponse) {
      console.log(`[NOAA-WA] chat=${sessionId} — Noa decidiu ficar quieta: ${result.noResponse.reason}`)
      return new Response('OK')
    }

    // Silêncio proposital em observer/human — sem fallback ao cliente.
    // EXCEÇÃO: se há orderPreview, manda HANDOFF_TO_ASHLEY_MESSAGES mesmo em mode=human
    // (cliente precisa saber que vai receber o link de pagamento).
    if ((result.mode === 'human' || result.mode === 'observer')
        && result.messagesToSend.length === 0
        && !result.orderPreview) {
      return new Response('OK')
    }

    // Sanitiza antes de enviar: remove **, —, hífens, normaliza corações
    const textMsgs = sanitizeNoaMessages(result.messagesToSend)
    const tailMsgs = sanitizeNoaMessages(result.orderPreview ? HANDOFF_TO_ASHLEY_MESSAGES : [])
    const allMessages = [...textMsgs, ...tailMsgs]

    if (allMessages.length === 0) {
      console.error('[NOAA-WA] empty output — fallback msg')
      await sendWhatsAppMessage(parsed.phone, 'Desculpa, tive um probleminha aqui. Pode repetir?')
      return new Response('OK')
    }

    await sendHumanizedMessages(parsed.phone, allMessages)

    for (const msg of textMsgs) {
      const isPdfLink = /drive\.google\.com/.test(msg)
      await insertMessage({
        sessionId,
        role: 'assistant',
        content: msg,
        channel: 'whatsapp',
        metadata: isPdfLink ? { event: 'pdf_link_sent' } : undefined,
        sentiment: isPdfLink ? null : (result.turnMeta?.sentiment || null),
        sentiment_intensity: isPdfLink ? null : (result.turnMeta?.intensity ?? null),
        intent: isPdfLink ? null : (result.turnMeta?.intent || null),
        urgency: isPdfLink ? null : (result.turnMeta?.urgency || null),
        red_flags: (result.turnMeta?.red_flags?.length ?? 0) > 0 ? result.turnMeta!.red_flags : null,
      })
    }
    for (const tail of tailMsgs) {
      await insertMessage({ sessionId, role: 'assistant', content: tail, channel: 'whatsapp' })
    }

    return new Response(JSON.stringify({ ok: true, processed: true }), { headers: { 'Content-Type': 'application/json' } })
  } catch (err) {
    console.error('[NOAA-WA] Handler error:', err)
    const msg = err instanceof Error ? err.message : String(err)
    return new Response(JSON.stringify({ ok: false, error: msg.slice(0, 500) }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    })
  }
})

