async function sendTypingAction(chatId: number | string) {
  try {
    await fetch(`${TG_API}/sendChatAction`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, action: 'typing' }),
    })
  } catch { /* best-effort */ }
}

async function sendTelegramMessage(chatId: number | string, text: string): Promise<number | null> {
  if (text.length > 4096) {
    const splitAt = text.lastIndexOf('\n', 4000) > 2000
      ? text.lastIndexOf('\n', 4000)
      : text.lastIndexOf(' ', 4000) > 2000
        ? text.lastIndexOf(' ', 4000)
        : 4000
    await sendTelegramMessage(chatId, text.substring(0, splitAt))
    return await sendTelegramMessage(chatId, text.substring(splitAt).trim())
  }

  try {
    const res = await fetch(`${TG_API}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text }),
    })
    const data = await res.json()
    if (!data.ok) console.error('[NOAA-TG] sendMessage failed:', data.description)
    return data.result?.message_id || null
  } catch (e) {
    console.error('[NOAA-TG] sendMessage error:', e)
    return null
  }
}

async function sendHumanizedMessages(chatId: number | string, messages: string[], testCollector?: string[]) {
  if (testCollector !== undefined) {
    testCollector.push(...messages)
    return
  }
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i]
    await sendTypingAction(chatId)
    const typingDelay = Math.min(3000, Math.max(800, msg.length * 50))
    await sleep(typingDelay)
    await sendTelegramMessage(chatId, msg)
    if (i < messages.length - 1) await sleep(300 + Math.random() * 500)
  }
}

function testResponse(collector: string[]): Response {
  return new Response(JSON.stringify({ messages: collector }), {
    headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
  })
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

