async function upsertCustomerFromTelegram(chatId: number, name?: string | null, username?: string | null) {
  try {
    const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
    const { data: existing } = await sb
      .from('noaa_customers')
      .select('id')
      .eq('telegram_chat_id', chatId)
      .maybeSingle()

    if (existing) {
      const updates: Record<string, any> = { last_contact: new Date().toISOString() }
      if (name) updates.name = name
      if (username) updates.telegram_username = username
      await sb.from('noaa_customers').update(updates).eq('id', existing.id)
      await sb.from('noaa_sessions').update({ customer_id: existing.id }).eq('chat_id', chatId)
    } else {
      const { data: created } = await sb
        .from('noaa_customers')
        .insert({
          name: name || null,
          telegram_username: username || null,
          telegram_chat_id: chatId,
          first_contact: new Date().toISOString(),
          last_contact: new Date().toISOString(),
        })
        .select('id')
        .single()
      if (created) {
        await sb.from('noaa_sessions').update({ customer_id: created.id }).eq('chat_id', chatId)
      }
    }
  } catch (e) {
    console.error('[NOAA-TG] upsertCustomer error:', e)
  }
}

