import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

const DEGUST_API_BASE = 'https://lx-degust-api-integracao-prd.azurewebsites.net'
// Token Degust expira em ~4h, vamos assumir 3h45m de validade segura
const TOKEN_VALIDITY_MS = 3.75 * 60 * 60 * 1000

interface DegustAuthResponse {
  // Formato real: { statusCode, acesso: { token, validade, ... } }
  statusCode?: number
  acesso?: {
    token?: string
    accessToken?: string
    validade?: string
    expiresIn?: number
    [key: string]: unknown
  }
  // Fallbacks para outros formatos possíveis
  token?: string
  accessToken?: string
  access_token?: string
  expiresIn?: number
  expires_in?: number
  [key: string]: unknown
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
  const SUPABASE_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  const DEGUST_USERNAME = Deno.env.get('DEGUST_USERNAME')
  const DEGUST_PASSWORD = Deno.env.get('DEGUST_PASSWORD')
  const DEGUST_FRANQUIA = Deno.env.get('DEGUST_FRANQUIA') ?? '3489'

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

  if (!DEGUST_USERNAME || !DEGUST_PASSWORD) {
    const err = 'DEGUST_USERNAME e DEGUST_PASSWORD devem estar configurados nos secrets do Supabase'
    console.error(`[degust-auth-refresh] ${err}`)
    return new Response(
      JSON.stringify({ error: err }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )
  }

  try {
    console.log('[degust-auth-refresh] Requesting new token from Degust API...')

    const authUrl = `${DEGUST_API_BASE}/api/usuario/autenticar?api-version=1.0`
    const authResponse = await fetch(authUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: JSON.stringify({
        usuario: DEGUST_USERNAME,
        senha: DEGUST_PASSWORD,
        codigoFranqueador: Number(DEGUST_FRANQUIA),
      }),
    })

    if (!authResponse.ok) {
      const errText = await authResponse.text()
      const errMsg = `Degust auth failed: ${authResponse.status} - ${errText}`
      console.error(`[degust-auth-refresh] ${errMsg}`)

      // Registrar erro na tabela
      await supabase.from('degust_auth').upsert({
        id: 1,
        token: 'ERROR',
        expires_at: new Date().toISOString(),
        last_error: errMsg,
      }, { onConflict: 'id' })

      return new Response(
        JSON.stringify({ error: errMsg }),
        { status: 502, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    const authData: DegustAuthResponse = await authResponse.json()

    // Degust retorna: { statusCode, acesso: { token, validade, ... } }
    const acesso = authData.acesso ?? {}
    const token = authData.token ?? authData.accessToken ?? authData.access_token
      ?? acesso.token ?? acesso.accessToken
    if (!token || typeof token !== 'string') {
      const errMsg = `Degust response missing token field. Received: ${JSON.stringify(authData).slice(0, 500)}`
      console.error(`[degust-auth-refresh] ${errMsg}`)
      return new Response(
        JSON.stringify({ error: errMsg }),
        { status: 502, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    // Calcular expires_at
    const expiresInSec = Number(
      authData.expiresIn ?? authData.expires_in ?? acesso.expiresIn ?? 0
    )
    let expiresAt: string
    if (expiresInSec > 0) {
      expiresAt = new Date(Date.now() + expiresInSec * 1000).toISOString()
    } else if (acesso.validade) {
      try { expiresAt = new Date(acesso.validade).toISOString() }
      catch { expiresAt = new Date(Date.now() + TOKEN_VALIDITY_MS).toISOString() }
    } else {
      expiresAt = new Date(Date.now() + TOKEN_VALIDITY_MS).toISOString()
    }

    // Salvar na tabela
    const { data: existing } = await supabase
      .from('degust_auth')
      .select('refresh_count')
      .eq('id', 1)
      .maybeSingle()

    const { error: upsertErr } = await supabase
      .from('degust_auth')
      .upsert({
        id: 1,
        token,
        expires_at: expiresAt,
        refreshed_at: new Date().toISOString(),
        refresh_count: (existing?.refresh_count ?? 0) + 1,
        last_error: null,
      }, { onConflict: 'id' })

    if (upsertErr) {
      console.error('[degust-auth-refresh] Failed to save token:', upsertErr)
      return new Response(
        JSON.stringify({ error: 'Failed to save token', details: upsertErr }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    console.log(`[degust-auth-refresh] Token refreshed. Expires at: ${expiresAt}`)

    return new Response(
      JSON.stringify({
        success: true,
        expires_at: expiresAt,
        refresh_count: (existing?.refresh_count ?? 0) + 1,
      }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )

  } catch (err) {
    const errMsg = err instanceof Error ? err.message : String(err)
    console.error('[degust-auth-refresh] Unexpected error:', errMsg)
    return new Response(
      JSON.stringify({ error: errMsg }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )
  }
})

