// Fetch sales for a single day from Degust API
async function fetchDayFromDegust(
  token: string,
  codigoLoja: number,
  date: string
): Promise<DegustTransaction[]> {
  const url = `${DEGUST_API_BASE}/api/financeiro/movimentacao-produtos?CodigoFranquia=${DEGUST_FRANQUIA}&CodigoLoja=${codigoLoja}&DataCaixa=${date}&api-version=1.0`

