    // sincronizado no meio do dia ficava congelado parcial pra sempre (o upsert
    // sobrescreve com o dia completo quando re-buscado).
    const missingDates = forceRefresh ? allDates : allDates.filter(d => !cachedSet.has(d))

    console.log(`[degust-sync] Range: ${startDate} to ${endDate} | Total: ${allDates.length} | Cached: ${cachedSet.size} | Missing: ${missingDates.length} | Force: ${forceRefresh}`)

    // Fetch missing dates from Degust API (5 concurrent)
    let syncedCount = 0
    let errorCount = 0

    if (missingDates.length > 0) {
      let currentToken = DEGUST_TOKEN
      const results = await fetchInBatches(missingDates, 5, async (date) => {
        try {
          return await fetchDayFromDegust(currentToken, degustLojaCode, date)
        } catch (err) {
          if ((err as Error).message === 'TOKEN_EXPIRED') {
