// Shared helper to fetch Degust token with auto-refresh
// Used by degust-sync-sales and any other function that talks to Degust

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

export class DegustTokenError extends Error {
  constructor(msg: string) {
    super(msg)
    this.name = 'DegustTokenError'
  }
}

/**
 * Fetch a valid Degust token from the degust_auth table.
 * If expired (or within 5 min of expiring), triggers degust-auth-refresh inline.
 *
 * Requires env: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
export async function getDegustToken(forceRefresh = false): Promise<string> {
  const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
  const SUPABASE_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

  if (!forceRefresh) {
    const { data, error } = await supabase
      .from('degust_auth')
      .select('token, expires_at')
      .eq('id', 1)
      .maybeSingle()

    if (error) throw new DegustTokenError(`Failed to read degust_auth: ${error.message}`)

    if (data?.token && data.token !== 'ERROR') {
      const expiresMs = new Date(data.expires_at).getTime()
      const fiveMinFromNow = Date.now() + 5 * 60 * 1000
      if (expiresMs > fiveMinFromNow) {
        return data.token
      }
      console.log(`[degust-token] Token expires at ${data.expires_at}, refreshing...`)
    } else {
      console.log('[degust-token] No token in DB, refreshing...')
    }
  }

  // Trigger refresh
  const refreshUrl = `${SUPABASE_URL}/functions/v1/degust-auth-refresh`
  const refreshRes = await fetch(refreshUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}`,
      'Content-Type': 'application/json',
    },
  })

  if (!refreshRes.ok) {
    const errText = await refreshRes.text()
    throw new DegustTokenError(`degust-auth-refresh failed: ${refreshRes.status} - ${errText}`)
  }

  const { data: fresh, error: freshErr } = await supabase
    .from('degust_auth')
    .select('token')
    .eq('id', 1)
    .single()

  if (freshErr || !fresh?.token || fresh.token === 'ERROR') {
    throw new DegustTokenError(`Token still not available after refresh: ${freshErr?.message ?? 'unknown'}`)
  }

  return fresh.token
}

