import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { getDegustToken } from '../_shared/degust-token.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

const API = 'https://lx-degust-api-integracao-prd.azurewebsites.net'
const FRANQUIA = 3489

interface TicketMedioRow {
  data: string           // "2026-03-08T00:00:00"
  desconto: number
  descontoReshop: number
  totalFaturado: number
  totalCupons: number
  ticketMedio: number
  quantidadeProdutos: number
  nomeFantasia: string
  codigoLoja: number
}

interface FlashVendaRow {
  codigoFranquia: number
  codigoLoja: number
  nomeFantasia: string
  dataCaixa: string       // "03/09/2026 00:00:00"
  ultimaAtualizacao: string
  previsaoAtualizacao: string
  totalVendas: number
  totalCupons: number
  ticketMedio: number
  quantidadeProduto: number
  caixaAberto: string     // "S" | "N"
}

interface DegustTransaction {
  codigoLoja: string
  nomeLoja: string
  dataCaixa: string
  hora: string
  codigoProduto: string
  nomeProduto: string
  quantidade: number
  valorUnitario: number
}

/** Cupom do POST /api/venda/relatorio-vendas (campos usados aqui). */
interface RelatorioVendasCupom {
  /** '1' = BALCÃO, '2' = DELIVERY (catálogo em /api/financeiro/tipos-venda). */
  tipoVenda: string
  /** Valor líquido do cupom como string ("86.00"). */
  valLiquido: string
  /** 'S' quando o cupom foi cancelado. */
  cancelada: string
  /** Data da venda "DD/MM/YYYY" (pode vir com hora — normalizamos). */
  dataVenda: string
}

/** Linha de resposta do modo includeDeliverySplit. */
interface DeliverySplitRow {
  data: string
  loja_id: number
  total_delivery: number
  cupons_delivery: number
}

/** Linha de resposta do modo includeHourly. */
interface HourlyRow {
  loja_id: number
  data: string
  byHour: Record<string, number>
}

/** "DD/MM/YYYY[ hh:mm:ss]" → "YYYY-MM-DD" (null se formato inesperado). */
function brDateToIso(value: string | undefined): string | null {
  const datePart = (value ?? '').split(' ')[0]
  const m = datePart.match(/^(\d{2})\/(\d{2})\/(\d{4})$/)
  if (!m) return null
  return `${m[3]}-${m[2]}-${m[1]}`
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
    const SUPABASE_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

    // Token automático via degust_auth + degust-auth-refresh (mesmo fluxo do
    // degust-sync-sales). Substitui o secret estático DEGUST_API_TOKEN, que
    // expirava a cada ~4h e derrubava o painel.
    let token = await getDegustToken()

    // fetch com retry único: se a API devolver 401, renova o token e repete.
    // Aceita init opcional (method/body/headers) — o Authorization é SEMPRE
    // reaplicado por cima (inclusive no retry, com o token renovado).
    const degustFetch = async (url: string, init?: RequestInit): Promise<Response> => {
      const doFetch = () =>
        fetch(url, {
          ...init,
          headers: { ...(init?.headers ?? {}), Authorization: `Bearer ${token}` },
        })
      let resp = await doFetch()
      if (resp.status === 401) {
        console.error('[degust-pos] 401 da API, renovando token e repetindo...')
        token = await getDegustToken(true)
        resp = await doFetch()
      }
      return resp
    }

    const {
      startDate,
      endDate,
      lojaId,
      includeProducts = false,
      includeDeliverySplit = false,
      // Delivery embutido no PDV existe SOMENTE no BSB Shopping (loja_id 6);
      // parametrizado para não hardcodar comportamento se isso mudar.
      deliveryLojaId = 6,
      includeHourly = false,
      hourlyDates = [],
    } = await req.json()

    if (!startDate || !endDate) {
      return new Response(
        JSON.stringify({ error: 'startDate and endDate required (YYYY-MM-DD)' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    // Security review F2: as datas são interpoladas em query strings da API
    // Degust — formato fechado YYYY-MM-DD evita injeção de parâmetros
    // (ex.: "2026-06-11&CodigoFranquia=9999").
    const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/
    if (!ISO_DATE_RE.test(String(startDate)) || !ISO_DATE_RE.test(String(endDate))) {
      return new Response(
        JSON.stringify({ error: 'startDate/endDate must match YYYY-MM-DD' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    // Security review F1: cap no fan-out de curvas horárias (stores ×
    // hourlyDates em Promise.all) — sem limite um caller poderia disparar
    // milhares de GETs paralelos contra a API Degust numa única invocação.
    const HOURLY_DATES_MAX = 7
    if (Array.isArray(hourlyDates) && hourlyDates.length > HOURLY_DATES_MAX) {
      return new Response(
        JSON.stringify({ error: `hourlyDates: máximo ${HOURLY_DATES_MAX} datas por chamada` }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }
    const hourlyDatesSafe: string[] = Array.isArray(hourlyDates)
      ? (hourlyDates as unknown[])
          .map((d) => String(d))
          .filter((d) => ISO_DATE_RE.test(d))
          .slice(0, HOURLY_DATES_MAX)
      : []

    // Mapeamento dinâmico Degust↔loja via degust_stores (cobre TODAS as lojas
    // Degust, incl. futuras). Substitui o hardcode {1:4, 2:5} que deixava a
    // BSB Shopping (código 3 → loja 6) sem remapeamento.
    const { data: stores, error: storesErr } = await supabase
      .from('degust_stores')
      .select('degust_loja_codigo, loja_id')
    if (storesErr || !stores || stores.length === 0) {
      return new Response(
        JSON.stringify({ error: `degust_stores indisponível: ${storesErr?.message ?? 'vazio'}` }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    const DEGUST_TO_LOJA: Record<number, number> = {}
    const LOJA_TO_DEGUST: Record<number, number> = {}
    for (const s of stores) {
      DEGUST_TO_LOJA[s.degust_loja_codigo] = s.loja_id
      LOJA_TO_DEGUST[s.loja_id] = s.degust_loja_codigo
    }

    const degustCode = lojaId ? LOJA_TO_DEGUST[lojaId] : undefined

    // ── 1) Flash Vendas (live today for all stores) ──
    let flashData: FlashVendaRow[] = []
    try {
      const flashResp = await degustFetch(
        `${API}/api/financeiro/flash-vendas?codigoFranqueador=${FRANQUIA}&api-version=1.0`
      )
      if (flashResp.ok) {
        flashData = await flashResp.json()
      } else {
        console.error('[degust-pos] flash-vendas error:', flashResp.status)
      }
    } catch (e) {
      console.error('[degust-pos] flash-vendas error:', e)
    }

    // ── 2) Ticket Medio (daily breakdown for date range) ──
    // Todas as lojas mapeadas (ou só a pedida via lojaId)
    const storeCodes = degustCode ? [degustCode] : stores.map(s => s.degust_loja_codigo)
    const dailyData: TicketMedioRow[] = []

    for (const code of storeCodes) {
      try {
        const tmResp = await degustFetch(
          `${API}/api/financeiro/ticket-medio?CodigoFranquia=${FRANQUIA}&CodigoLoja=${code}&DataInicial=${startDate}&DataFinal=${endDate}&api-version=1.0`
        )
        if (tmResp.ok) {
          const rows: TicketMedioRow[] = await tmResp.json()
