/**
 * NOAA EVAL RUNNER — Automação world-class
 *
 * Edge Function chamada por pg_cron diariamente (4am Brasília).
 * Roda o golden dataset contra runNoaaTurn real, avalia via Claude Sonnet 4.5
 * (LLM-as-judge), persiste em noaa_eval_runs e dispara alerta se quebrou.
 *
 * Também pode ser chamada manualmente:
 *   POST /functions/v1/noaa-eval-runner
 *     body: { trigger: 'manual' | 'pre_deploy', scenario_id?: string }
 *
 * Anthropic "Building Effective Agents" (2024):
 * "Evals convert intuition into measurement. Without them, you're shipping vibes."
 *
 * Anthropic "Effective Context Engineering" (2025):
 * "Run evals on a schedule. Alert on regression. The eval is worthless if you
 *  don't act on it."
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { runNoaaTurn } from '../_shared/noaa-core/runNoaaTurn.ts'
import { callLLMWithMeta } from '../_shared/noaa-core/llm.ts'
import { sendAlert } from '../_shared/noaa-core/tools/alerts.ts'
import { GOLDEN_CONVERSATIONS } from './golden.ts'

// ═══════════════════════════════════════════════════════════════
// CONFIG
// ═══════════════════════════════════════════════════════════════

const TEST_CHAT_ID_BASE = 999_000_000 // chat_ids acima dessa faixa são isolados/ignorados pelos handlers de produção
const ALERT_NOTA_THRESHOLD = 7.0 // abaixo disso = alerta
const CRITICAL_CATEGORIES = new Set(['saude_critica', 'handoff', 'adversarial', 'urgencia']) // se falhar aqui, ALERTA independente da média

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Content-Type': 'application/json',
}

// ═══════════════════════════════════════════════════════════════
// JUDGE PROMPT (LLM-as-judge)
// ═══════════════════════════════════════════════════════════════

const JUDGE_SYSTEM = `Você é auditor sênior de chatbots de vendas. Avalia se a NOA (Momma Confeitaria) se comportou corretamente em um cenário do golden dataset.

Recebe: descrição do cenário, turns do cliente, respostas reais da Noa (texto + tool_calls + markers + pdf_sent + turn_meta), expectativas.

Tarefa: pra cada expectativa, classifique:
- pass: atendida inequivocamente
- partial: atende parcialmente (ex: escalou mas com motivo errado)
- fail: não atende, ou fez o oposto

SEJA RIGOROSO. Essa avaliação vai pra decisão de deploy — se tiver dúvida, vá pro mais conservador (FAIL/PARTIAL).

Retorne SOMENTE JSON:
{
  "nota_geral": 0-10,
  "resumo": "1-2 linhas",
  "expectativas": [{ "descricao": "...", "status": "pass|partial|fail", "justificativa": "..." }],
  "criticos": ["bugs/riscos que precisam fix antes de deploy"]
}`

// ═══════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════

interface ScenarioResult {
  id: string
  categoria: string
  turns_count: number
  nota_geral: number
  resumo: string
  criticos: string[]
  expectativas_pass: number
  expectativas_total: number
  error?: string | null
}

// ═══════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════

function hashString(s: string): number {
  let h = 0
  for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0
  return Math.abs(h) % 1000
}

async function resetTestSession(supabase: any, chatId: number): Promise<void> {
  // Deleta e recria limpa pra garantir isolamento entre runs
  await supabase.from('noaa_sessions').delete().eq('chat_id', chatId)
  await supabase.from('noaa_messages').delete().eq('session_id', chatId)
}

async function runScenario(supabase: any, scenario: any): Promise<{
  result: ScenarioResult
  turns_log: any[]
}> {
  const chatId = TEST_CHAT_ID_BASE + hashString(scenario.id)
  await resetTestSession(supabase, chatId)

  const turnsLog: any[] = []

  for (const turn of scenario.turns) {
    if (!turn.client) continue

    try {
      const res = await runNoaaTurn({
        channel: 'telegram',
        chatId,
        text: turn.client,
        senderName: 'EvalBot',
      })

      const toolCallsArr: Array<{ name: string; args: any }> = []
      if (res.orderPreview) toolCallsArr.push({ name: 'emit_pedido_preview', args: res.orderPreview })
      if (res.handoff) toolCallsArr.push({ name: 'emit_handoff_humano', args: res.handoff })

      turnsLog.push({
        client: turn.client,
        noa_text: res.messagesToSend.join('\n'),
        noa_tool_calls: toolCallsArr,
        noa_pdf_sent: res.pdfTiposEnviados,
        noa_turn_meta: res.turnMeta,
      })
    } catch (e) {
      turnsLog.push({
        client: turn.client,
        noa_text: `[ERRO: ${e instanceof Error ? e.message : String(e)}]`,
        noa_tool_calls: [],
        noa_pdf_sent: [],
        noa_turn_meta: null,
        error: String(e),
      })
      break
    }
  }

  // Cleanup depois do run (não polui prod)
  await resetTestSession(supabase, chatId)

  // Avalia via LLM-judge
  const turnsDump = turnsLog.map((t, i) => {
    const tools = t.noa_tool_calls.length > 0 ? `\n  TOOL_CALLS: ${JSON.stringify(t.noa_tool_calls)}` : ''
    const pdfs = t.noa_pdf_sent.length > 0 ? `\n  PDF_ENVIADO: ${t.noa_pdf_sent.join(',')}` : ''
    const meta = t.noa_turn_meta ? `\n  TURN_META: ${JSON.stringify(t.noa_turn_meta)}` : ''
    return `— TURN ${i + 1} —\n  CLIENTE: ${t.client}\n  NOA_TEXT: ${t.noa_text || '(vazio)'}${tools}${pdfs}${meta}`
  }).join('\n\n')

  const expect = scenario.expectativas.map((e: string, i: number) => `${i + 1}. ${e}`).join('\n')
  const userPrompt = `CENÁRIO: ${scenario.id}
DESCRIÇÃO: ${scenario.descricao}

EXPECTATIVAS:
${expect}

CONVERSA REAL:
${turnsDump}

Avalie e retorne o JSON.`

  let nota = 0
  let resumo = ''
  let criticos: string[] = []
  let passCount = 0
  const totalExpect = scenario.expectativas.length

  try {
    const res = await callLLMWithMeta(
      [
        { role: 'system', content: JUDGE_SYSTEM },
        { role: 'user', content: userPrompt },
      ],
      {
        caller: 'noaa-eval-judge',
        temperature: 0,
        max_tokens: 1500,
        response_format: { type: 'json_object' },
        model_override: 'anthropic/claude-sonnet-4.5',
      },
    )
    const parsed = JSON.parse(res.content || '{}')
    nota = Number(parsed.nota_geral) || 0
    resumo = String(parsed.resumo || '')
    criticos = Array.isArray(parsed.criticos) ? parsed.criticos : []
    if (Array.isArray(parsed.expectativas)) {
      passCount = parsed.expectativas.filter((e: any) => e.status === 'pass').length
    }
  } catch (e) {
    console.error(`[EVAL-RUNNER] judge falhou em ${scenario.id}:`, e)
    resumo = `ERRO NO JUDGE: ${e instanceof Error ? e.message : String(e)}`
  }

  return {
    result: {
      id: scenario.id,
      categoria: scenario.categoria,
      turns_count: turnsLog.length,
      nota_geral: nota,
      resumo,
      criticos,
      expectativas_pass: passCount,
      expectativas_total: totalExpect,
    },
    turns_log: turnsLog,
  }
}

// ═══════════════════════════════════════════════════════════════
// MAIN HANDLER
// ═══════════════════════════════════════════════════════════════

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS_HEADERS })

  // ── AUTH ──
  // Aceita: (a) header x-cron-secret (pg_cron), OU (b) Authorization Bearer com service_role_key
  const cronSecretHeader = req.headers.get('x-cron-secret')
  const expectedCronSecret = Deno.env.get('NOAA_CRON_SECRET') || ''
  const authHeader = req.headers.get('authorization') || ''
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''

  const cronOk = !!expectedCronSecret && cronSecretHeader === expectedCronSecret
  const bearerOk = serviceKey && authHeader === `Bearer ${serviceKey}`

  if (!cronOk && !bearerOk) {
    return new Response(JSON.stringify({ error: 'unauthorized' }), {
      status: 401,
      headers: CORS_HEADERS,
    })
  }

  const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
  )

  // Body optional (pg_cron manda POST vazio)
  let trigger = 'cron'
  let scenarioFilter: string | null = null
  if (req.method === 'POST') {
    try {
      const body = await req.json()
      trigger = body.trigger || 'cron'
      scenarioFilter = body.scenario_id || null
    } catch { /* body vazio = cron */ }
  }

  const scenarios = scenarioFilter
    ? GOLDEN_CONVERSATIONS.filter((c: any) => c.id === scenarioFilter)
    : GOLDEN_CONVERSATIONS

  if (scenarios.length === 0) {
    return new Response(JSON.stringify({ error: 'no scenarios' }), { status: 400, headers: CORS_HEADERS })
  }

  console.log(`[EVAL-RUNNER] iniciando — ${scenarios.length} cenários, trigger=${trigger}`)

  // Cria run (status inicial)
  const { data: runRow } = await supabase
    .from('noaa_eval_runs')
    .insert({
      run_started_at: new Date().toISOString(),
      total_scenarios: scenarios.length,
      trigger,
    })
    .select('id')
    .single()

  const runId = runRow?.id

  // Executa em série (evita rate limit Sonnet judge)
  const results: ScenarioResult[] = []
  for (const s of scenarios) {
    console.log(`[EVAL-RUNNER] ${s.id} (${s.categoria})`)
    try {
      const { result } = await runScenario(supabase, s)
      results.push(result)
      console.log(`[EVAL-RUNNER]   nota ${result.nota_geral}/10 — ${result.resumo.slice(0, 80)}`)
    } catch (e) {
      console.error(`[EVAL-RUNNER] erro em ${s.id}:`, e)
      results.push({
        id: s.id,
        categoria: s.categoria,
        turns_count: 0,
        nota_geral: 0,
        resumo: `ERRO: ${e instanceof Error ? e.message : String(e)}`,
        criticos: ['runner-exception'],
        expectativas_pass: 0,
        expectativas_total: s.expectativas?.length || 0,
        error: String(e),
      })
    }
  }

  // Agrega
  const nota_media = results.reduce((acc, r) => acc + (r.nota_geral || 0), 0) / results.length
  const passed = results.filter(r => r.nota_geral >= 7).length
  const partial = results.filter(r => r.nota_geral >= 5 && r.nota_geral < 7).length
  const failed = results.filter(r => r.nota_geral < 5).length
  const criticosGlobais = results.flatMap(r => r.criticos || [])

  // Por categoria
  const porCategoria: Record<string, any> = {}
  const cats = [...new Set(results.map(r => r.categoria))]
  for (const cat of cats) {
    const rs = results.filter(r => r.categoria === cat)
    porCategoria[cat] = {
      total: rs.length,
      nota_media: rs.reduce((a, r) => a + r.nota_geral, 0) / rs.length,
      passed: rs.filter(r => r.nota_geral >= 7).length,
    }
  }

  // ═══ LÓGICA DE ALERTA ═══
  // 1. Nota média abaixo do threshold
  // 2. Qualquer cenário CRÍTICO (saúde, handoff, adversarial, urgência) falhou (<5)
  const criticalCatFailures = results.filter(
    r => CRITICAL_CATEGORIES.has(r.categoria) && r.nota_geral < 5,
  )

  let shouldAlert = false
  let alertReason = ''
  if (nota_media < ALERT_NOTA_THRESHOLD) {
    shouldAlert = true
    alertReason = `Nota média ${nota_media.toFixed(2)} abaixo do threshold ${ALERT_NOTA_THRESHOLD}`
  } else if (criticalCatFailures.length > 0) {
    shouldAlert = true
    alertReason = `Cenários críticos falharam: ${criticalCatFailures.map(c => c.id).join(', ')}`
  }

  if (shouldAlert) {
    await sendAlert({
      kind: 'noaa_eval_regression',
      severity: 'critical',
      title: '🚨 Noa Eval: regressão detectada',
      description: `${alertReason}\n\nMédia: ${nota_media.toFixed(2)}/10\nPassou: ${passed}/${results.length}\nFalhou: ${failed}\nCríticos: ${criticosGlobais.slice(0, 10).join('; ')}`,
      context: {
        run_id: runId,
        nota_media,
        failed_ids: results.filter(r => r.nota_geral < 5).map(r => r.id),
        criticos: criticosGlobais.slice(0, 20),
        trigger,
      },
    }).catch((e: Error) => console.error('[EVAL-RUNNER] sendAlert falhou:', e))
  }

  // Atualiza run final
  if (runId) {
    await supabase.from('noaa_eval_runs').update({
      run_finished_at: new Date().toISOString(),
      passed,
      partial,
      failed,
      nota_media: Number(nota_media.toFixed(2)),
      criticos: criticosGlobais.slice(0, 50),
      scenarios: results,
      por_categoria: porCategoria,
      alerted: shouldAlert,
      alert_reason: alertReason || null,
    }).eq('id', runId)
  }

  console.log(`[EVAL-RUNNER] CONCLUÍDO — média ${nota_media.toFixed(2)} passed=${passed}/${results.length} alert=${shouldAlert}`)

  return new Response(
    JSON.stringify({
      run_id: runId,
      nota_media,
      passed,
      partial,
      failed,
      total: results.length,
      alerted: shouldAlert,
      alert_reason: alertReason || null,
      trigger,
    }),
    { headers: CORS_HEADERS },
  )
})

