/**
 * Cron diário: para cada férias aprovadas com aviso liberado (35d antes do gozo)
 * e que ainda não foi assinado, cria notificação no master.
 *
 * Schedule sugerido: diariamente às 08:00 BRT.
 */

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

Deno.serve(async () => {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const supabase = createClient(supabaseUrl, serviceKey, {
    auth: { persistSession: false },
  });

  const today = new Date().toISOString().slice(0, 10);

  // 1) Buscar marcações aprovadas com aviso liberado e ainda não assinado
  const { data: marcacoes, error } = await supabase
    .from('ferias_marcacoes')
    .select(`id, employee_id, data_inicio, aviso_pdf_url, aviso_assinado_url,
             employees!inner(nome_completo)`)
    .eq('status', 'aprovado')
    .not('aviso_pdf_url', 'is', null)
    .is('aviso_assinado_url', null);

  if (error) {
    return new Response(JSON.stringify({ error: error.message }), { status: 500 });
  }

  let criadas = 0;
  for (const m of marcacoes ?? []) {
    // só lembra se aviso já liberável (35d antes ou menos)
    const inicio = new Date(m.data_inicio + 'T00:00:00');
    const lib = new Date(inicio);
    lib.setDate(lib.getDate() - 35);
    if (new Date() < lib) continue;

    // Evitar duplicar lembrete do mesmo dia
    const { data: existente } = await supabase
      .from('notificacoes_master')
      .select('id')
      .eq('tipo', 'ferias_aviso_pendente_assinatura')
      .eq('ref_id', m.id)
      .gte('created_at', today + 'T00:00:00')
      .limit(1);
    if (existente && existente.length > 0) continue;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const empNome = (m as any).employees?.nome_completo ?? 'funcionário';
    await supabase.from('notificacoes_master').insert({
      tipo: 'ferias_aviso_pendente_assinatura',
      ref_tipo: 'ferias_marcacao',
      ref_id: m.id,
      employee_id: m.employee_id,
      titulo: `Aviso de férias pendente de assinatura: ${empNome}`,
      descricao: `Início do gozo em ${m.data_inicio}. Colha a assinatura do colaborador e anexe o documento.`,
    });
    criadas++;
  }

  return new Response(JSON.stringify({ ok: true, lembretes_criados: criadas }), {
    headers: { 'Content-Type': 'application/json' },
  });
});

// MIA Code-Native — OTLP Trace Export Endpoint (P0)
//
// Endpoint pull GET /mia-otel-export?since=ISO_TIMESTAMP
// Retorna OTLP JSON com spans gen_ai.* dos step results recentes.
// Ingest direto em qualquer OTLP receiver (Sentry, Arize, FutureAGI,
// Tempo, Honeycomb, Jaeger).
//
// Auth: requer service role key OR query param ?key= que bate com env
// MIA_OTEL_EXPORT_KEY (opt-in). Permite scraping de fora sem service key.
//
// Doc: docs/mia/HARNESS.md §10.1

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { stepsToOtelTrace, spansToOtlpExport, type StepResultRow } from '../mia/otel-adapter.ts'

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
const OTEL_EXPORT_KEY = Deno.env.get('MIA_OTEL_EXPORT_KEY')
const SERVICE_NAME = Deno.env.get('MIA_OTEL_SERVICE_NAME') ?? 'momma-mia'
const SERVICE_VERSION = Deno.env.get('MIA_OTEL_SERVICE_VERSION') ?? '1.0'

const supabaseAdmin = (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY)
    ? createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
    : null

const CORS_HEADERS = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, content-type, x-otel-export-key',
    'Access-Control-Allow-Methods': 'GET, OPTIONS',
}

function json(data: unknown, status = 200): Response {
    return new Response(JSON.stringify(data), {
        status,
        headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
    })
}

serve(async (req: Request) => {
    if (req.method === 'OPTIONS') return new Response(null, { headers: CORS_HEADERS })
    if (req.method !== 'GET') return json({ error: 'method_not_allowed' }, 405)
    if (!supabaseAdmin) return json({ error: 'supabase_not_configured' }, 500)

    const url = new URL(req.url)
    // Auth: aceita Bearer service role OU header x-otel-export-key OU query ?key=
    const authHeader = req.headers.get('authorization') ?? ''
    const exportKey = req.headers.get('x-otel-export-key') ?? url.searchParams.get('key') ?? ''
    const hasServiceAuth = authHeader.includes(SUPABASE_SERVICE_ROLE_KEY ?? '__none__')
    const hasExportKey = OTEL_EXPORT_KEY && exportKey === OTEL_EXPORT_KEY
    if (!hasServiceAuth && !hasExportKey) {
        return json({ error: 'unauthorized', hint: 'use Authorization: Bearer <service_role> OR x-otel-export-key OR ?key=' }, 401)
    }

    // Query params
    const sinceParam = url.searchParams.get('since')  // ISO 8601
    const limitParam = url.searchParams.get('limit')
    const limit = Math.min(parseInt(limitParam ?? '500', 10) || 500, 5000)
    const since = sinceParam ?? new Date(Date.now() - 15 * 60 * 1000).toISOString()  // default últimos 15min

    try {
        const { data, error } = await supabaseAdmin
            .from('mia_glass_box_step_results')
            .select('plan_id, round, step_index, user_id, op, selector_key, value, success, error_message, duration_ms, page_path_at_execute, device_info, viewport_width, viewport_height, created_at')
            .gte('created_at', since)
            .order('created_at', { ascending: true })
            .limit(limit)
        if (error) return json({ error: 'db_query_failed', detail: error.message }, 500)

        const spans = stepsToOtelTrace((data ?? []) as StepResultRow[])
        const otlp = spansToOtlpExport(spans, {
            serviceName: SERVICE_NAME,
            serviceVersion: SERVICE_VERSION,
        })

        return json({
            export_format: 'otlp/json',
            since,
            limit,
            rows_processed: (data ?? []).length,
            spans_emitted: spans.length,
            traces_emitted: new Set(spans.map((s) => s.traceId)).size,
            data: otlp,
        })
    } catch (err) {
        console.error('[mia-otel-export] error:', err)
        return json({ error: 'export_failed', detail: String(err).slice(0, 200) }, 500)
    }
})

-- Log bruto de TODO webhook WhatsApp que chega ao edge function noaa-whatsapp.
